import {projectNavigation} from './oncall-navigation.js';
import {regionalEditor} from './oncall-regional-editor.js';
import {remindersView} from './oncall-reminders.js';
import {createOncallStatus} from "./oncall-status.js";
import {calendarView} from "./oncall-calendar.js";
import {createOncallAlerts} from './oncall-alerts.js';
import {createOncallResponse} from './oncall-response.js';
import {escapeHtml as esc} from './message-format.js';
import {generatePlan,localInstant,localAt,addDays,effectivePerson,resultValue} from './oncall-planning.js';
const ms=ns=>Number(BigInt(ns)/1_000_000n);
const time=(ns,zone)=>new Intl.DateTimeFormat('en-GB',{timeZone:zone,dateStyle:'medium',timeStyle:'short'}).format(ms(ns));
const date=(ns,zone)=>new Intl.DateTimeFormat('en-GB',{timeZone:zone,dateStyle:'medium'}).format(ms(ns));
const key=()=>Array.from(crypto.getRandomValues(new Uint8Array(16)),b=>b.toString(16).padStart(2,'0')).join('');
const field=(id,title,value='',attrs='')=>`<label for="${id}">${title}</label><input id="${id}" value="${esc(value)}" ${attrs.includes('type=')?'':'type="text"'} ${attrs}>`;
const errorText=e=>e?.message||'Connection interrupted. Your change may have been saved; refresh to check.';

export function createOncall({root,api,session,getMe,backendId,alertBase}) {
  let generation=0,refreshTimer=null,context='';
  const serviceStatus=createOncallStatus({root,api,session,getMe});
  const response=createOncallResponse({root,api,session,getMe});
  const alerts=createOncallAlerts({root,api,session,getMe,endpoint:alertBase||`https://${backendId}.icp.net`});
  const token=()=>session.load();
  const identity=()=>{const me=getMe();return me&&['admin','agent'].includes(me.role)?JSON.stringify([me.id,me.role]):'';};
  const active=stamp=>{if(stamp!==generation)return false;if(!context||context!==identity()){clear();return false;}return true;};
  function clear(){response.clear();alerts.clear();serviceStatus.clear();generation++;context='';clearTimeout(refreshTimer);root.replaceChildren();}
  function notice(text){const el=root.querySelector('[data-oc-status]');if(el)el.textContent=text;}
  const status='<p data-oc-status role="status" aria-live="polite"></p>';
  function heading(title,description,action=''){return`<div class="page-heading"><div><span class="eyebrow">ON-CALL</span><h2>${esc(title)}</h2><p class="lead">${esc(description)}</p></div>${action}</div>`;}
  async function run(button,work,done){const stamp=generation;if(!active(stamp)||button.disabled)return;button.disabled=true;notice('Saving…');try{const value=resultValue(await work());if(active(stamp))await done?.(value);}catch(e){if(active(stamp))notice(errorText(e));}finally{if(active(stamp)&&button.isConnected)button.disabled=false;}}
  async function show(id='',mode='') {
    response.clear();alerts.clear();serviceStatus.clear();const stamp=++generation;context=identity();clearTimeout(refreshTimer);
    root.innerHTML='<p role="status">Loading on-call planning…</p>';
    if(!active(stamp)){clear();return;}
    try{
      if(id==='new'){
        if(getMe().role!=='admin')throw Error('Project setup requires a Hub-assigned Desk administrator.');
        const customers=await api().listCustomerProjects(token());if(active(stamp))projectEditor(customers, mode);return;
      }
      if(!id){const projects=await api().oncallProjects(token());if(active(stamp))overview(projects);return;}
      const [workspace]=await api().oncallWorkspace(token(),BigInt(id));if(!active(stamp))return;
      if(!workspace){root.innerHTML=heading('Project unavailable','Your Hub account may no longer have access to this team.');return;}
      if(mode==='status'||mode.startsWith('status-')){await serviceStatus.show(workspace,mode);return;}
      if(mode==='sources'||mode.startsWith('source-')){await alerts.show(workspace,mode);return;}
      if(mode==='incidents'||mode==='response-settings'||mode.startsWith('incident-')){await response.show(workspace,mode);return;}
      const [calendar]=await api().oncallCalendar(token(),workspace.project.id);if(!active(stamp))return;if(!calendar)throw Error('Your project access changed.');workspace.calendar=calendar;
      if(mode==='reminders'){const [view]=await api().oncallReminders(token(),workspace.project.id);if(active(stamp)){if(!view)throw Error('Project access changed.');remindersView({root,w:workspace,view,api,token,run,show,status});}return;}
      if(mode==='availability'||mode==='project-settings'){calendarView({root,w:workspace,calendar,mode,getMe,api,token,run,show,status});return;}
      if(['new','regional-new','simple-new'].includes(mode)&&workspace.canManage){if(calendar.settings.archivedAt>0n)throw Error('Restore the archived project before planning.');const last=workspace.plans.filter(p=>p.published).sort((a,b)=>a.endAt>b.endAt?-1:1)[0];const prior=last?(await api().oncallPlan(token(),last.id))[0]:null;const saved=last?(await api().oncallRegionalRecipe(token(),last.id))[0]:null;if(active(stamp)){if(mode==='regional-new'||mode==='new'&&saved)regionalEditor({root,w:workspace,saved,run,api,token,requestKey:key(),status});else planEditor(workspace,prior?.plan);}return;}
      const now=BigInt(Date.now())*1_000_000n;
      const chosen=mode?workspace.plans.find(p=>String(p.id)===mode):workspace.plans.find(p=>p.published&&p.startAt<=now&&p.endAt>now)||workspace.plans.filter(p=>p.endAt>now).sort((a,b)=>a.startAt<b.startAt?-1:1)[0]||workspace.plans[0];
      if(mode&&!chosen)throw Error('This planning period is unavailable. Open the project to choose another period.');
      const view=chosen?(await api().oncallPlan(token(),chosen.id))[0]:null;if(!active(stamp))return;
      if(chosen&&!view)throw Error('This plan is no longer available. Refresh to check your access.');
      if(view){view.effective=(await api().oncallEffectivePlan(token(),view.plan.id))[0];if(!view.effective)throw Error('Effective coverage could not be loaded.');view.regional=(await api().oncallRegionalRecipe(token(),view.plan.id))[0];}if(active(stamp))workspaceView(workspace,view);
    }catch(e){if(active(stamp)){root.innerHTML=heading('Planning could not be loaded',errorText(e))+'<button data-oc-retry>Try again</button>';root.querySelector('[data-oc-retry]').onclick=()=>show(id,mode);}}
  }
  function overview(projects){
    root.innerHTML=heading('On-call projects','Your teams, their coverage and what needs attention.',getMe().role==='admin'?'<a class="button primary" href="#/oncall/new">Set up on-call <span aria-hidden="true">＋</span></a>':'')+`<div class="oc-projects">${projects.sort((a,b)=>Number(!!a.archived)-Number(!!b.archived)).map(p=>`<a class="card oc-project" href="#/oncall/${p.id}"><span class="eyebrow">${Object.hasOwn(p.scope,'customer')?'CUSTOMER PROJECT':'INTERNAL OPERATIONS'}</span><h3>${esc(p.name)}${p.archived?' · Archived':''}</h3><p>${esc(p.description||p.services.join(' · '))}</p><span class="oc-project-foot">View coverage <span aria-hidden="true">↗</span></span></a>`).join('')||'<div class="card oc-empty"><span class="oc-mark" aria-hidden="true">◷</span><h3>Make the next handoff easy.</h3><p>Start with a team and a few weeks of coverage. Review the plan before publishing.</p>'+(getMe().role==='admin'?'<a class="button primary" href="#/oncall/new">Create your first project</a>':'<p class="kv">A Desk administrator can enable on-call for your Hub team.</p>')+'</div>'}</div><p class="oc-footnote">Coverage, incidents and status updates in one project. Confirm service and prepare payroll under Time & compensation.</p>`;
  }
  function projectEditor(customers, mode){
    const requestKey=key();
    root.innerHTML='<a class="back-link" href="#/oncall">← On-call</a>'+heading('Who are we keeping covered?','Start with an internal team or an existing customer project.')+`<form id="ocProjectForm" class="card oc-form"><div class="row"><div><label for="ocScope">Workspace</label><select id="ocScope"><option value="internal">Internal operations</option>${customers.map(p=>`<option value="${p.id}">${esc(p.name)} · Customer support</option>`).join('')}</select></div><div id="ocTeamField">${field('ocGroup','Team from Hub','','list="groupList" maxlength="80" placeholder="Blank = admins only"')}</div></div>${field('ocName','Project name','','required minlength="2" maxlength="80" placeholder="e.g. Product operations"')}${field('ocDescription','Short description','','maxlength="300" placeholder="What this team keeps running"')}${field('ocServices','Services · comma separated','','required placeholder="e.g. Website, API, Sign-in"')}<p class="kv" id="ocAccessHelp">Team members need the Desk Agent role in Hub. Administrators retain access.</p><div class="btnrow"><button class="primary" type="submit">Create project</button><a class="button" href="#/oncall">Cancel</a></div>${status}</form>`;
    const get=id=>root.querySelector('#'+id);
    get('ocScope').onchange=()=>{const p=customers.find(p=>String(p.id)===get('ocScope').value);get('ocTeamField').hidden=!!p;get('ocAccessHelp').textContent=p?'Uses this customer project’s existing Hub support team and access rules.':'Team members need the Desk Agent role in Hub. Administrators retain access.';if(p)get('ocName').value=p.name;};
    if(mode?.startsWith('customer-')){get('ocScope').value=mode.slice(9);get('ocScope').onchange();}
    get('ocProjectForm').onsubmit=e=>{e.preventDefault();const scope=get('ocScope').value==='internal'?{internal:get('ocGroup').value.trim()}:{customer:BigInt(get('ocScope').value)};run(e.submitter,()=>api().createOncallProject(token(),requestKey,{name:get('ocName').value.trim(),description:get('ocDescription').value.trim(),scope,services:get('ocServices').value.split(',').map(s=>s.trim()).filter(Boolean)}),v=>{location.hash=`#/oncall/${v.id}/new`;});};
  }
  function planEditor(w,prior){
    const last=w.plans.filter(p=>p.published&&ms(p.endAt)>Date.now()).sort((a,b)=>a.endAt>b.endAt?-1:1)[0];
    const requestKey=key(),zone=last?.timezone||Intl.DateTimeFormat().resolvedOptions().timeZone||'UTC';
    const following=last?localAt(Math.ceil(ms(last.endAt)/60000)*60000,zone):null;
    const tomorrow=following?.slice(0,10)||addDays(localAt(Date.now(),zone).slice(0,10),1),handoff=following?.slice(11,16)||'09:00',selected={primary:[],backup:[]};
    if(prior)for(const[k,layer]of [['primary',0n],['backup',1n]]){const shifts=prior.input.shifts.filter(s=>s.layer===layer&&s.personId&&w.members.some(m=>m.id===s.personId)).sort((a,b)=>a.startAt<b.startAt?-1:1);const order=[...new Set(shifts.map(s=>s.personId))],last=order.indexOf(shifts.at(-1)?.personId);selected[k]=[...order.slice(last+1),...order.slice(0,last+1)];}
    root.innerHTML=`<a class="back-link" href="#/oncall/${w.project.id}">← ${esc(w.project.name)}</a>`+heading('Plan your next few weeks.','Choose the coverage, set the rotation, then review every handoff.',`<a class="button" href="#/oncall/${w.project.id}/regional-new">Plan across regions ↗</a>`)+`<form id="ocPlanForm" class="oc-editor"><div class="card oc-form"><span class="eyebrow">01 · COVERAGE</span><div class="oc-templates" role="group" aria-label="Coverage template">${[['always','Around the clock','24 hours, every day'],['afterhours','After hours','18:00–08:00 + weekends'],['weekdays','Working hours','Mon–Fri, 08:00–18:00']].map(([v,t,s],i)=>`<label class="oc-template"><input type="radio" name="coverage" value="${v}" ${i===0?'checked':''}><strong>${t}</strong><span>${s}</span></label>`).join('')}</div><div class="row"><div>${field('ocStart','First day',tomorrow,'type="date" required')}</div><div><label for="ocWeeks">Planning period</label><select id="ocWeeks"><option value="2">2 weeks</option><option value="4" selected>4 weeks</option><option value="8">8 weeks</option><option value="12">12 weeks</option></select></div></div><div class="row"><div>${field('ocZone','Timezone',zone,'required list="ocZones"')}</div><div>${field('ocHandoff','Handoff time',handoff,'type="time" required')}</div><div><label for="ocRotation">Change responder</label><select id="ocRotation"><option value="7">Every week</option><option value="1">Every day</option></select></div></div><datalist id="ocZones">${['UTC','Europe/Zurich','Europe/London','America/New_York','America/Los_Angeles','Asia/Singapore','Australia/Sydney'].map(z=>`<option value="${z}">`).join('')}</datalist><details class="oc-backup"><summary>Public holidays & closures</summary><label for="ocHolidays">Non-working dates · comma separated</label><input id="ocHolidays" placeholder="2026-12-25, 2026-12-26"><p class="kv">Working-hours plans omit these dates. After-hours plans cover the full day. Around-the-clock coverage remains unchanged. Pay rules are configured separately.</p></details><p class="kv">Local times follow daylight-saving changes. The preview shows the exact dates; this plan ends after the selected period.</p></div><div class="card oc-form"><span class="eyebrow">02 · ROTATION</span><h3>Who takes the first shift?</h3><p class="kv">Select people in rotation order. Choose a separate backup team if needed.</p><div data-roster="primary"></div><details class="oc-backup"><summary>Add a backup rotation</summary><div data-roster="backup"></div></details><p class="kv">Eligible people come from the project’s Hub team. Change access in Hub.</p></div><div class="oc-editor-footer"><button type="submit" class="primary">Review plan →</button><a class="button" href="#/oncall/${w.project.id}">Cancel</a>${status}</div></form>`;
    function paint(kind){const box=root.querySelector(`[data-roster="${kind}"]`);box.innerHTML=`<div class="oc-people">${w.members.map(p=>{const i=selected[kind].indexOf(p.id);return`<button type="button" class="oc-person ${i>=0?'selected':''}" data-person="${esc(p.id)}" aria-pressed="${i>=0}"><span class="oc-order">${i>=0?i+1:'＋'}</span>${esc(p.name)}</button>`;}).join('')||'<p>No eligible responders. Check the team and Desk roles in Hub.</p>'}</div>`;box.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{const id=b.dataset.person;selected[kind]=selected[kind].includes(id)?selected[kind].filter(x=>x!==id):[...selected[kind],id];paint(kind);});}
    paint('primary');paint('backup');
    if(prior){const coverage=(prior.input.template||'').split(' · ')[0];const radio=root.querySelector(`[name="coverage"][value="${['always','weekdays','afterhours'].includes(coverage)?coverage:'always'}"]`);if(radio)radio.checked=true;root.querySelector('#ocRotation').value=(prior.input.template||'').endsWith('daily')?'1':'7';root.querySelector('.oc-editor').insertAdjacentHTML('afterbegin','<p class="oc-footnote">Rotation continues with the person after the last planned responder. Review dates, holidays and any manual exceptions before publishing.</p>');}
    root.querySelector('#ocPlanForm').onsubmit=e=>{e.preventDefault();try{const v=id=>root.querySelector('#'+id).value;const input=generatePlan({projectId:w.project.id,startDate:v('ocStart'),weeks:Number(v('ocWeeks')),timezone:v('ocZone'),handoff:v('ocHandoff'),rotationDays:Number(v('ocRotation')),coverage:root.querySelector('[name="coverage"]:checked').value,holidays:v('ocHolidays').split(',').map(s=>s.trim()).filter(Boolean),...selected});run(e.submitter,()=>api().saveOncallPlan(token(),0n,0n,requestKey,input),r=>{location.hash=`#/oncall/${w.project.id}/${r.id}`;});}catch(e){notice(errorText(e));}};
  }
  function workspaceView(w,view){
    const p=view?.plan,archived=w.calendar?.settings.archivedAt>0n,cutoff=view?.effective?.cancellation?.[0],now=BigInt(Date.now())*1_000_000n,published=!!p?.publication?.length,zone=p?.input.timezone||'UTC';
    const names=new Map([...(p?.publication?.[0]?.names||[]),...(view?.effective?.covers||[]).map(s=>({id:s.toPersonId,name:s.toName})),...(view?.swaps||[]).map(s=>({id:s.toPersonId,name:s.toName})),...w.members].map(p=>[p.id,p.name]));
    const name=id=>names.get(id)||'Unavailable responder';
    const person=(i)=>effectivePerson(p,view.swaps,i);
    const segments=view?.effective?.segments||[];
    const current=segments.map(s=>({...s,index:Number(s.shift),id:s.personId})).filter(s=>s.startAt<=now&&s.endAt>now)||[];
    const liveIssues=view?.issues.filter(i=>i.endAt>now)||[];
    root.innerHTML=`<a class="back-link" href="#/oncall">← On-call projects</a>`+heading(w.project.name,w.project.services.join(' · '),w.canManage&&!archived?`<a class="button primary" href="#/oncall/${w.project.id}/new">Plan next period ＋</a>`:'')+`<div class="oc-toolbar"><div>${Object.hasOwn(w.project.scope,'customer')?`<a class="button" href="#/customers/${w.project.scope.customer}">Customer requests ↗</a>`:'<span class="eyebrow">INTERNAL OPERATIONS</span>'}</div><div>${w.plans.length?`<label class="sr-only" for="ocPeriod">Planning period</label><select id="ocPeriod">${w.plans.map(x=>`<option value="${x.id}" ${p?.id===x.id?'selected':''}>${date(x.startAt,x.timezone)} – ${date(x.endAt,x.timezone)} · ${x.published?'Published':'Draft'}</option>`).join('')}</select>`:''}<button id="ocRefresh">Refresh</button></div></div>`;
    root.querySelector('#ocRefresh').onclick=()=>show(String(w.project.id),p?String(p.id):'');const period=root.querySelector('#ocPeriod');if(period)period.onchange=()=>{location.hash=`#/oncall/${w.project.id}/${period.value}`;};
    root.insertAdjacentHTML('beforeend',projectNavigation(w));
    if(archived)root.insertAdjacentHTML("beforeend",'<p class="oc-issues">Archived project · history and reporting remain available.</p>');
    if(!p){root.insertAdjacentHTML('beforeend',`<section class="card oc-empty"><span class="oc-mark" aria-hidden="true">◷</span><h3>No coverage published yet.</h3><p>${w.canManage?'Build a rotation and review the coverage before your team sees it.':'Your administrator is preparing the team’s first plan.'}</p>${w.canManage&&!archived?`<a class="button primary" href="#/oncall/${w.project.id}/new">Create a plan</a>`:''}</section>`);return;}
    const currentText=cutoff&&now>=cutoff.from?'Coverage ended by an administrator':!published?'Draft · not effective':now>=p.input.endAt?'Period ended':now<p.input.startAt?'Starts '+date(p.input.startAt,zone):current.length?current.map(s=>`${p.input.layers[Number(s.layer)]}: ${s.id?name(s.id):'Unassigned'}${s.id&&(!w.members.some(m=>m.id===s.id)||w.calendar?.absences.some(a=>!a.cancelledAt&&a.personId===s.id&&a.startAt<=now&&a.endAt>now))?' · unavailable':''}`).join(' · '):p.input.windows.some(s=>s.startAt<=now&&s.endAt>now)?'Coverage missing now':'Outside required hours';
    const ordered=(published?segments.map(s=>({...s,index:Number(s.shift)})):p.input.shifts.map((s,i)=>({...s,index:i}))).sort((a,b)=>a.startAt===b.startAt?Number(a.layer-b.layer):a.startAt<b.startAt?-1:1);
    const next=ordered.find(s=>s.startAt>now);
    root.insertAdjacentHTML('beforeend',`<div class="oc-summary"><section class="card"><span class="eyebrow">${!published?'DRAFT COVERAGE':now<p.input.startAt?'UPCOMING COVERAGE':now>=p.input.endAt||cutoff&&now>=cutoff.from?'COVERAGE HISTORY':'ON DUTY NOW'}</span><strong>${esc(currentText)}</strong><span>${esc(zone)}</span></section><section class="card"><span class="eyebrow">${published?'NEXT SHIFT':'FIRST SHIFT'}</span><strong>${next?esc(time(next.startAt,zone)):'No upcoming shift'}</strong><span>${next?esc(next.personId?name(next.personId):'Unassigned')+' · ':''}${published?'Coverage ends':'Draft ends'} ${esc(time(cutoff?.from<p.input.endAt?cutoff.from:p.input.endAt,zone))}</span></section><section class="card ${liveIssues.length?'oc-attention':''}"><span class="eyebrow">NEEDS ATTENTION</span><strong>${liveIssues.length?`${liveIssues.length} uncovered interval${liveIssues.length===1?'':'s'}`:(archived?'Project archived':now>=p.input.endAt||cutoff&&now>=cutoff.from?'No active coverage in this plan':'Required hours covered')}</strong><span>${published?'Current Hub eligibility checked':'Draft coverage · review before publishing'}</span></section></div><p class="oc-footnote">Checked <span data-oc-checked>${esc(new Date().toLocaleTimeString())}</span> · Coverage plan · Incident notifications are configured separately.</p>${status}<div id="ocReview"></div><div id="ocSwaps"></div><details class="card oc-plan-check"><summary>Check coverage at a specific time</summary><p class="kv">See who covers a selected time. Simulation sends no messages.</p><div class="oc-simulation"><div class="row"><div>${field('ocSimTime','Local date & time',localAt(Math.ceil(ms(p.input.startAt)/60000)*60000,zone),'type="datetime-local"')}</div><button id="ocSim">Check coverage</button></div><div id="ocSimResult" role="status"></div></div></details><div class="section-heading"><h3>${published?'Team schedule':'Review the schedule'}</h3><span class="kv">${ordered.length} intervals · ${esc(zone)}</span></div><div class="card flat oc-schedule"><div class="table-scroll"><table><thead><tr><th>When</th><th>Response layer</th><th>Responder</th><th>Action</th></tr></thead><tbody>${ordered.map(({index:i,...s})=>`<tr><td><strong>${esc(time(s.startAt,zone))}</strong><span class="rowsub">until ${esc(time(s.endAt,zone))}</span></td><td>${esc(p.input.layers[Number(s.layer)])}</td><td>${published?esc(s.personId?name(s.personId):'Unassigned'):`<select data-assign="${i}" aria-label="Responder for shift ${i+1}"><option value="">Unassigned · leave a gap</option>${w.members.map(m=>`<option value="${esc(m.id)}" ${s.personId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select>`}</td><td>${published&&!archived&&s.endAt>now&&(w.canManage||s.personId===getMe().id)?`<button class="sm" data-cover="${i}" data-start="${s.startAt}" data-end="${s.endAt}" data-person="${esc(s.personId)}">Request cover</button>`:s.endAt<=now?'Past shift':published?'Scheduled':'Draft'}</td></tr>`).join('')}</tbody></table></div></div><div id="ocCoverForm"></div><details class="oc-history" data-publication-history><summary>Publication & replacement history</summary><div>${published?`<p>Published ${esc(time(p.publication[0].at,zone))}. Planned duty is not proof of work performed.</p>`:'<p>This draft is visible to administrators only.</p>'}${[...view.swaps,...(view.effective?.covers||[])].map(s=>`<p>${esc(name(s.fromPersonId))} → ${esc(name(s.toPersonId))} · ${esc(Object.keys(s.state)[0])}<br><span class="kv">${esc(s.reason)} · requested ${esc(time(s.requestedAt,zone))}</span></p>`).join('')}</div></details>`);
    if(view.regional){const r=view.regional.recipe,clock=n=>`${String(Math.floor(Number(n)/60)).padStart(2,'0')}:${String(Number(n)%60).padStart(2,'0')}`;root.querySelector('#ocReview').insertAdjacentHTML('beforebegin',`<details class="oc-history"><summary>Regional rules · ${r.regions.length} regions · ${Object.hasOwn(r.requirement,'continuous')?'24/7 primary requirement':'regional hours only'}</summary><p class="kv">Earlier regions own overlapping time. The exact assignments below are authoritative.${view.regional.edited?' Manual assignments differ from the original rules.':''}</p>${r.regions.map((region,i)=>`<p><strong>${i+1}. ${esc(region.name)}</strong> · ${esc(region.timezone)} · ${clock(region.startMinute)}–${clock(region.endMinute)}<br><span class="kv">${region.days.length===7?'Every day':'Configured weekdays'} · ${region.holidays.length} holiday dates · ${Object.hasOwn(region.backupMode,'none')?'no backup':Object.hasOwn(region.backupMode,'nonworking')?'weekend/holiday backup':'backup on primary days'}</span></p>`).join('')}</details>`);}
    const review=root.querySelector('#ocReview');
    const issuesList=()=>view.issues.length?`<details class="oc-issues" open><summary>${view.issues.length} intervals need coverage</summary>${view.issues.map(i=>`<p>${esc(p.input.layers[Number(i.layer)])} · ${esc(time(i.startAt,zone))} – ${esc(time(i.endAt,zone))}${Object.hasOwn(i.kind,'unavailable')?' · responder unavailable':''}</p>`).join('')}</details>`:'';
    review.innerHTML=issuesList()+(!published?`<div class="oc-publish"><div><strong>Ready for your team?</strong><p class="kv">Publishing fixes these dates. Later replacements require acceptance.</p>${view.issues.length?'<label class="checkline"><input id="ocAcceptGaps" type="checkbox"> Publish with the listed coverage gaps</label>':''}</div><div class="btnrow"><button id="ocSaveAssignments" disabled>Save changes</button><button id="ocPublish" class="primary">Publish plan</button></div></div>`:'');
    let changed=false;
    root.querySelectorAll('[data-assign]').forEach(select=>select.onchange=()=>{p.input.shifts[Number(select.dataset.assign)].personId=select.value;changed=true;root.querySelector('#ocSaveAssignments').disabled=false;root.querySelector('#ocPublish').disabled=true;notice('Save your changes to recalculate coverage before publication.');});
    if(!published){root.querySelector('#ocSaveAssignments').onclick=e=>run(e.currentTarget,()=>api().saveOncallPlan(token(),p.id,p.revision,p.requestKey,p.input),()=>show(String(w.project.id),String(p.id)));root.querySelector('#ocPublish').onclick=e=>{if(changed)return;run(e.currentTarget,()=>api().publishOncallPlan(token(),p.id,p.revision,!!root.querySelector('#ocAcceptGaps')?.checked),()=>show(String(w.project.id),String(p.id)));};}
    root.querySelector('#ocSim').onclick=()=>{const el=root.querySelector('#ocSimResult');try{const at=localInstant(root.querySelector('#ocSimTime').value,zone);if(at<p.input.startAt||at>=(cutoff?.from??p.input.endAt)){el.textContent='Outside this planning period. No coverage is defined by this plan.';return;}const windows=p.input.windows.filter(s=>s.startAt<=at&&s.endAt>at);el.innerHTML=windows.length?windows.map(win=>{const shift=(published?segments:p.input.shifts).find(s=>s.layer===win.layer&&s.startAt<=at&&s.endAt>at),id=shift?.personId||'',absent=w.calendar?.absences.some(a=>!a.cancelledAt&&a.personId===id&&a.startAt<=at&&a.endAt>at);return`<p><strong>${esc(p.input.layers[Number(win.layer)])}</strong> · ${id&&!absent&&w.members.some(m=>m.id===id)?esc(name(id)):'Coverage missing — no eligible responder'}</p>`;}).join(''):'Outside required support hours.';}catch(e){el.textContent=errorText(e);}};
    const allSwaps=[...view.swaps,...(view.effective?.covers||[]).map(c=>({...c,interval:true}))];
    const pending=allSwaps.filter(s=>Object.hasOwn(s.state,'pending'));
    root.querySelector('#ocSwaps').innerHTML=pending.map(s=>`<section class="card oc-swap"><div><strong>${(s.startAt??p.input.shifts[Number(s.shift)].startAt)<=now?'Cover request expired':'Cover requested'} · ${esc(name(s.toPersonId))}</strong><p>${esc(time((s.startAt??p.input.shifts[Number(s.shift)].startAt),zone))} · ${esc(s.reason)}</p><span class="kv">${esc(name(s.fromPersonId))} remains assigned until acceptance.</span></div><div class="btnrow">${s.toPersonId===getMe().id&&(s.startAt??p.input.shifts[Number(s.shift)].startAt)>now?`<button class="primary" data-decision="accept" data-swap="${s.id}" data-interval="${!!s.interval}">Accept shift</button><button data-decision="decline" data-swap="${s.id}" data-interval="${!!s.interval}">Decline</button>`:''}${w.canManage||s.requestedBy===getMe().id?`<button data-decision="cancel" data-swap="${s.id}" data-interval="${!!s.interval}">Cancel request</button>`:''}</div></section>`).join('');
    root.querySelectorAll('[data-decision]').forEach(b=>b.onclick=()=>run(b,()=>api()[b.dataset.interval==='true'?'decideOncallInterval':'decideOncallCover'](token(),p.id,p.revision,BigInt(b.dataset.swap),{[b.dataset.decision]:null}),()=>show(String(w.project.id),String(p.id))));
    root.querySelectorAll('[data-cover]').forEach(b=>b.onclick=()=>{
      const index=Number(b.dataset.cover),from=b.dataset.person,box=root.querySelector('#ocCoverForm'),start=BigInt(b.dataset.start),end=BigInt(b.dataset.end);
      box.innerHTML=`<form class="card oc-form"><h3>Cover all or part of this shift</h3><p>${esc(name(from))} stays responsible until the replacement accepts.</p><div class="row"><div>${field('ocCoverStart','From · '+esc(zone),localAt(Math.ceil(Math.max(ms(start),Date.now()+120000)/60000)*60000,zone),'type="datetime-local" required')}</div><div>${field('ocCoverEnd','Until',localAt(ms(end),zone),'type="datetime-local" required')}</div></div><label for="ocReplacement">Ask a teammate</label><select id="ocReplacement" required><option value="">Choose a responder</option>${w.members.filter(m=>m.id!==from).map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('')}</select>${field('ocReason','Reason','','required maxlength="240" placeholder="A short operational reason; no private details"')}<div class="btnrow"><button type="submit" class="primary">Request cover</button><button type="button" id="ocCancelCover">Cancel</button></div><p class="kv">The selected person accepts in Desk. Enable planning reminders to notify them through Hub; this is separate from incident paging.</p></form>`;
      box.querySelector('#ocCancelCover').onclick=()=>box.replaceChildren();box.querySelector('form').onsubmit=e=>{e.preventDefault();try{const value=id=>box.querySelector('#'+id).value;const a=localInstant(value('ocCoverStart'),zone),b=localInstant(value('ocCoverEnd'),zone);run(e.submitter,()=>api().requestOncallInterval(token(),p.id,p.revision,BigInt(index),a,b,value('ocReplacement'),value('ocReason').trim()),()=>show(String(w.project.id),String(p.id)));}catch(e){notice(errorText(e));}};box.scrollIntoView?.({block:'center'});box.querySelector('select').focus();
    });
    const lifecycle=document.createElement('details');lifecycle.className='oc-history';lifecycle.innerHTML=`<summary>Plan history & actions</summary>${cutoff?`<p>Coverage ends ${esc(time(cutoff.from,zone))} · ${esc(cutoff.reason)}</p>`:''}<button id="ocExportPlan">Download plan history</button>${w.canManage&&!cutoff?(published&&p.input.endAt>now?`<form id="ocEndPlan"><label for="ocCutoff">End coverage from · ${esc(zone)}</label><input type="datetime-local" id="ocCutoff" value="${localAt(Math.ceil((Date.now()+120000)/60000)*60000,zone)}" required><label for="ocEndReason">Reason</label><input id="ocEndReason" minlength="3" maxlength="240" required><p class="kv">Past duty remains recorded. Ending future coverage does not resolve incidents or cancel work records.</p><button>End future coverage</button></form>`:!published?'<button id="ocDiscard">Discard unpublished draft</button>':''):''}`;const history=root.querySelector('[data-publication-history]');if(history){lifecycle.querySelector('summary').after(history.querySelector('div'));history.remove();}root.append(lifecycle);
    root.querySelector('#ocExportPlan').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({project:w.project,plan:p,regional:view.regional,effective:view.effective,swaps:view.swaps},(_,v)=>typeof v==='bigint'?v.toString():v,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`oncall-plan-${p.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
    const endForm=root.querySelector('#ocEndPlan');if(endForm)endForm.onsubmit=e=>{e.preventDefault();try{const from=localInstant(root.querySelector('#ocCutoff').value,zone);run(e.submitter,()=>api().cancelOncallPlan(token(),p.id,p.revision,from,root.querySelector('#ocEndReason').value.trim()),()=>show(String(w.project.id),String(p.id)));}catch(e){notice(errorText(e));}};
    const discard=root.querySelector('#ocDiscard');if(discard)discard.onclick=()=>run(discard,()=>api().discardOncallDraft(token(),p.id,p.revision),()=>{location.hash=`#/oncall/${w.project.id}`;show(String(w.project.id));});
    // Poll authority even while editing. Repaint only when the view changes, and
    // defer non-critical repaints while the user is interacting with controls.
    if(published)watchPublished(w,view);
  }
  function fingerprint(w,view){
    const now=BigInt(Date.now())*1_000_000n,p=view.plan;
    const position=s=>s.endAt<=now?'past':s.startAt>now?'future':'current';
    return JSON.stringify([w,p.revision,view.effective,view.swaps,view.issues.map(i=>({...i,startAt:i.startAt<now?'started':i.startAt})),p.input.shifts.map(position),p.input.windows.map(position)],(_,v)=>typeof v==='bigint'?String(v):v);
  }
  function watchPublished(w,view){
    const stamp=generation,baseline=fingerprint(w,view),id=String(w.project.id),mode=String(view.plan.id);
    const schedule=()=>{clearTimeout(refreshTimer);refreshTimer=setTimeout(poll,30000);};
    async function poll(){
      if(!active(stamp))return;
      if(document.hidden){schedule();return;}
      try{
        const [fresh]=await api().oncallWorkspace(token(),w.project.id);if(!active(stamp))return;
        if(!fresh)throw Error('Your Hub account no longer has access to this project.');
        const [updated]=await api().oncallPlan(token(),view.plan.id);if(!active(stamp))return;
        if(!updated)throw Error('This plan is no longer available to your Hub account.');
        updated.regional=view.regional;fresh.calendar=(await api().oncallCalendar(token(),w.project.id))[0];updated.effective=(await api().oncallEffectivePlan(token(),view.plan.id))[0];if(!active(stamp))return;if(!fresh.calendar||!updated.effective)throw Error('Your project access changed.');
        const editing=root.querySelector('#ocCoverForm form')||root.contains(document.activeElement)&&document.activeElement?.matches('input,select,textarea,button');
        if(fingerprint(fresh,updated)!==baseline&&!editing){
          const value=root.querySelector('#ocSimTime')?.value,hadResult=!!root.querySelector('#ocSimResult')?.textContent;
          workspaceView(fresh,updated);
          if(value){root.querySelector('#ocSimTime').value=value;if(hadResult)root.querySelector('#ocSim').click();}
          return;
        }
        const checked=root.querySelector('[data-oc-checked]');if(checked)checked.textContent=new Date().toLocaleTimeString();
        if(fingerprint(fresh,updated)!==baseline)notice('The plan has changed. Finish your input, then refresh before submitting.');
        schedule();
      }catch(e){if(active(stamp)){root.innerHTML=heading('Coverage needs a fresh check',errorText(e))+'<button data-oc-retry>Try again</button>';root.querySelector('[data-oc-retry]').onclick=()=>show(id,mode);}}
    }
    schedule();
  }
  return{show,clear};
}
